"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[128],{87:function(n){n.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-01-eda</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="0272c627" class="cell markdown">\n<h1 id="лабораторная-работа--1-разведочный-анализ-данных-eda-и-предобработка">Лабораторная\nработа № 1. Разведочный анализ данных (EDA) и предобработка</h1>\n<p><strong>Курс:</strong> Классическое машинное обучение, 4 курс\nприкладной математики</p>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Освоить первичный анализ данных, визуализацию, очистку и подготовку\nданных для построения моделей машинного обучения.</p>\n<p><strong>Используемые инструменты:</strong> <code>pandas</code>,\n<code>matplotlib</code>, <code>seaborn</code>,\n<code>sklearn.preprocessing</code>,\n<code>sklearn.model_selection</code>.</p>\n</div>\n<div id="4c093352" class="cell markdown">\n<h3 id="регламент-сдачи">Регламент сдачи</h3>\n<p>Работа сдаётся в виде этого же ноутбука, дополненного вашим кодом.\nОбязательно:</p>\n<ol>\n<li>Читаемый код с комментариями.</li>\n<li>Визуализации (графики, таблицы).</li>\n<li><strong>Текстовый вывод после каждого задания</strong> — не только\nкод, но и объяснение результата.</li>\n<li>Финальный вывод по работе.</li>\n</ol>\n<p><strong>Критерии оценки:</strong> корректность реализации — 30 %,\nкачество визуализаций и анализа — 20 %, обоснованность выводов — 20 %,\nсравнение с эталонными реализациями — 15 %, оригинальность и\nдополнительная работа — 15 %.</p>\n<blockquote>\n<p>Ячейки, помеченные <code># TODO</code>, нужно заполнить\nсамостоятельно. Ячейки с готовым кодом можно просто выполнить — они\nподготавливают данные и графики.</p>\n</blockquote>\n</div>\n<div id="a4df38f9" class="cell markdown">\n<h2 id="подготовка-окружения">Подготовка окружения</h2>\n</div>\n<div id="9b79b783" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> seaborn <span class="im">as</span> sns</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="op">%</span>matplotlib inline</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="dv">7</span>, <span class="dv">4</span>),</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a>sns.set_palette(<span class="st">&quot;viridis&quot;</span>)</span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span></span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span></code></pre></div>\n</div>\n<div id="6b7523cb" class="cell markdown">\n<h2 id="задание-1-загрузка-датасета">Задание 1. Загрузка датасета</h2>\n<p>Возьмите <code>titanic</code> из <code>seaborn</code> (есть пропуски\nи категориальные признаки — то, что нужно для EDA). Альтернатива —\n<code>wine</code> из <code>sklearn.datasets</code>.</p>\n</div>\n<div id="a72c745c" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>df <span class="op">=</span> sns.load_dataset(<span class="st">&quot;titanic&quot;</span>)</span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;Размер:&quot;</span>, df.shape)</span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>df.head()</span></code></pre></div>\n</div>\n<div id="eefdbdbc" class="cell markdown">\n<h2 id="задание-2-первичный-анализ">Задание 2. Первичный анализ</h2>\n<p>Нужно получить:</p>\n<ul>\n<li>описательные статистики для числовых признаков;</li>\n<li>анализ пропусков и выбросов;</li>\n<li>разделение признаков на числовые и категориальные.</li>\n</ul>\n</div>\n<div id="3a14f2cf" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Описательные статистики числовых признаков</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: выведите df.describe() и прокомментируйте: где разброс подозрительно велик?</span></span></code></pre></div>\n</div>\n<div id="0c13715b" class="cell code">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Пропуски: количество и доля по каждому столбцу</span></span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте таблицу вида [признак | пропусков, шт | пропусков, %], отсортированную по убыванию</span></span></code></pre></div>\n</div>\n<div id="ec8cd82c" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Разделение признаков по типам</span></span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a>numeric_features <span class="op">=</span> df.select_dtypes(include<span class="op">=</span>[np.number]).columns.tolist()</span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a>categorical_features <span class="op">=</span> df.select_dtypes(include<span class="op">=</span>[<span class="st">&quot;object&quot;</span>, <span class="st">&quot;category&quot;</span>, <span class="st">&quot;bool&quot;</span>]).columns.tolist()</span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;Числовые:      &quot;</span>, numeric_features)</span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;Категориальные:&quot;</span>, categorical_features)</span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: проверьте список глазами. Какие признаки формально числовые,</span></span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       но по смыслу категориальные (например, pclass)? Перенесите их вручную.</span></span></code></pre></div>\n</div>\n<div id="98f578c3" class="cell markdown">\n<p><strong>Вывод по заданию 2:</strong> <em>опишите, какие проблемы вы\nнашли в данных.</em></p>\n</div>\n<div id="198b1583" class="cell markdown">\n<h2 id="задание-3-визуализация">Задание 3. Визуализация</h2>\n<p>Постройте четыре типа графиков:</p>\n<ol>\n<li>гистограммы распределений числовых признаков;</li>\n<li>ящики с усами (boxplot) для поиска выбросов;</li>\n<li>матрицу корреляций в виде тепловой карты;</li>\n<li>попарные зависимости (pairplot) для 3–4 самых важных признаков.</li>\n</ol>\n</div>\n<div id="01775979" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="co"># 1. Гистограммы</span></span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: df[numeric_features].hist(...) либо цикл с sns.histplot по подграфикам</span></span></code></pre></div>\n</div>\n<div id="73f77d42" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="co"># 2. Boxplot для поиска выбросов</span></span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте boxplot для числовых признаков.</span></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       Подсказка: признаки в разных масштабах — либо нормируйте, либо стройте по отдельности</span></span></code></pre></div>\n</div>\n<div id="e4a06e8e" class="cell code">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="co"># 3. Матрица корреляций</span></span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: corr = df[numeric_features].corr(); sns.heatmap(corr, annot=True, cmap=&quot;coolwarm&quot;, center=0)</span></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       Есть ли пары признаков с |corr| &gt; 0.8? Чем это грозит линейным моделям?</span></span></code></pre></div>\n</div>\n<div id="e748875e" class="cell code">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="co"># 4. Попарные зависимости</span></span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: sns.pairplot(df[&lt;ваши 3-4 признака&gt; + [&quot;survived&quot;]], hue=&quot;survived&quot;)</span></span></code></pre></div>\n</div>\n<div id="ca4e00e1" class="cell markdown">\n<p><strong>Вывод по заданию 3:</strong> <em>что видно на графиках —\nасимметрия, выбросы, мультиколлинеарность?</em></p>\n</div>\n<div id="69573090" class="cell markdown">\n<h2 id="задание-4-предобработка">Задание 4. Предобработка</h2>\n<ul>\n<li>заполнить пропуски (медиана для числовых, мода для\nкатегориальных);</li>\n<li>закодировать категориальные признаки (One-Hot или Label\nEncoding);</li>\n<li>отмасштабировать числовые признаки (<code>StandardScaler</code> или\n<code>MinMaxScaler</code>).</li>\n</ul>\n</div>\n<div id="f36b10f7" class="cell code">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler, OneHotEncoder</span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: заполните пропуски</span></span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a><span class="co">#   числовые:        df[col].fillna(df[col].median())</span></span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a><span class="co">#   категориальные:  df[col].fillna(df[col].mode()[0])</span></span></code></pre></div>\n</div>\n<div id="f13310b5" class="cell code">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: закодируйте категориальные признаки.</span></span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       Подумайте: где уместен One-Hot, а где Label Encoding? Что произойдёт</span></span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       с линейной моделью, если закодировать &#39;deck&#39; числами 0..7?</span></span></code></pre></div>\n</div>\n<div id="a9a91a99" class="cell code">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: отмасштабируйте числовые признаки.</span></span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       ВАЖНО: fit только на обучающей выборке, иначе произойдёт утечка данных.</span></span></code></pre></div>\n</div>\n<div id="250b1c49" class="cell markdown">\n<h2 id="задание-5-разделение-выборки">Задание 5. Разделение выборки</h2>\n<p>Разбейте данные на обучающую (80 %) и тестовую (20 %) части\n<strong>со стратификацией</strong> по целевой переменной.</p>\n</div>\n<div id="af449c65" class="cell code">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a>TARGET <span class="op">=</span> <span class="st">&quot;survived&quot;</span></span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: X, y = ...</span></span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: X_train, X_test, y_train, y_test = train_test_split(</span></span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a><span class="co">#           X, y, test_size=0.2, stratify=y, random_state=RANDOM_STATE)</span></span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a><span class="co"># Проверьте, что доли классов в train и test совпадают</span></span></code></pre></div>\n</div>\n<div id="ebf5881f" class="cell markdown">\n<h2 id="задание-6-сохранение-результата">Задание 6. Сохранение\nрезультата</h2>\n<p>Сохраните предобработанные данные — они понадобятся в следующих\nработах.</p>\n</div>\n<div id="2b8676c3" class="cell code">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: сохраните в файлы, например</span></span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a><span class="co">#   X_train.to_csv(&quot;data/X_train.csv&quot;, index=False)</span></span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a><span class="co"># либо целиком: np.savez(&quot;data/prepared.npz&quot;, X_train=X_train, ...)</span></span></code></pre></div>\n</div>\n<div id="699646a0" class="cell markdown">\n<h2 id="дополнительное-задание">Дополнительное задание</h2>\n<p>Соберите предобработку в <code>sklearn.pipeline.Pipeline</code> с\n<code>ColumnTransformer</code>, чтобы её можно было переиспользовать в\nследующих работах одной строкой.</p>\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.compose <span class="im">import</span> ColumnTransformer</span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> Pipeline</span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.impute <span class="im">import</span> SimpleImputer</span></code></pre></div>\n</div>\n<div id="bce665c3" class="cell code">\n<div class="sourceCode" id="cb16"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb16-1"><a href="#cb16-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: соберите ColumnTransformer:</span></span>\n<span id="cb16-2"><a href="#cb16-2" aria-hidden="true" tabindex="-1"></a><span class="co">#   числовые       -&gt; SimpleImputer(strategy=&quot;median&quot;)   + StandardScaler()</span></span>\n<span id="cb16-3"><a href="#cb16-3" aria-hidden="true" tabindex="-1"></a><span class="co">#   категориальные -&gt; SimpleImputer(strategy=&quot;most_frequent&quot;) + OneHotEncoder(handle_unknown=&quot;ignore&quot;)</span></span></code></pre></div>\n</div>\n<div id="1fe58412" class="cell markdown">\n<h2 id="финальный-вывод">Финальный вывод</h2>\n<p><em>Напишите здесь связный вывод по работе (5–10\nпредложений):</em></p>\n<ul>\n<li>какие методы вы применили и почему;</li>\n<li>какие результаты получили в числах;</li>\n<li>где реализация «с нуля» разошлась с эталоном из <code>sklearn</code>\nи в чём причина;</li>\n<li>что бы вы улучшили, будь у вас больше времени.</li>\n</ul>\n</div>\n</body>\n</html>\n'}}]);